    /* No __wasm_simd128__, no AVX512F/AVX2/SSSE3 intrinsics headers and no
       aarch64+NEON: the reference implementation is selected. */
    unsafe {
        fill_segment = crate::crypto_pwhash::argon2::fill_block_ref::_sodium_argon2_fill_segment_ref
    };

